<script setup>
import {computed,ref,onMounted,onUnmounted} from 'vue'
import {fetchAuthConfig,sendEmailCode,workspaceRequest} from '../api/client'
const props=defineProps({t:Object,initialMode:{type:String,default:'login'},required:Boolean,isNative:Boolean})
const emit=defineEmits(['authenticated','close'])
const mode=ref(props.initialMode),email=ref(localStorage.getItem('mhp.registeredEmail')||''),password=ref(''),confirmation=ref(''),username=ref(''),code=ref(''),challenge=ref(''),remember=ref(true),busy=ref(false),error=ref(''),notice=ref(''),enabled=ref(false),cooldown=ref(0)
const en=computed(()=>props.t.account.breadcrumb==='Account'),text=(zh,enText)=>en.value?enText:zh
let timer
onMounted(async()=>{timer=setInterval(()=>{if(cooldown.value>0)cooldown.value--},1000);try{enabled.value=(await fetchAuthConfig()).email_enabled}catch{}})
onUnmounted(()=>clearInterval(timer))
function switchMode(value){mode.value=value;error.value='';notice.value='';password.value='';confirmation.value='';code.value='';challenge.value=''}
async function send(){if(busy.value||cooldown.value)return;busy.value=true;error.value='';try{const r=mode.value==='reset'?await workspaceRequest('/auth/password/reset-code','POST',{email:email.value.trim()}):await sendEmailCode(email.value.trim());challenge.value=r.challenge_id;cooldown.value=r.retry_after;notice.value=mode.value==='reset'?text('若该邮箱已注册，将收到找回密码验证码。','If registered, this email will receive a reset code.'):text('验证码已发送，用于首次注册或旧账号一次性绑定密码。','Code sent for registration or one-time password setup.')}catch(e){error.value=e.message}finally{busy.value=false}}
async function submit(){if(busy.value)return;error.value='';if(mode.value!=='login'&&password.value!==confirmation.value){error.value=text('两次密码不一致','Passwords do not match');return}busy.value=true;try{if(mode.value==='reset'){await workspaceRequest('/auth/password/reset','POST',{challenge_id:challenge.value,code:code.value,new_password:password.value});switchMode('login');notice.value=text('密码已重置，请使用新密码登录，其他设备已退出。','Password reset. Sign in again; other devices were signed out.');return}const payload=mode.value==='register'?{challenge_id:challenge.value,code:code.value,username:username.value.trim(),password:password.value,remember:remember.value}:{email:email.value.trim(),password:password.value,remember:remember.value};const result=await workspaceRequest('/auth/'+(mode.value==='register'?'register':'login'),'POST',payload);localStorage.setItem('mhp.registeredEmail',result.user.email);emit('authenticated',result.user)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="auth-overlay" @keydown.esc="!required&&emit('close')"><section class="auth-dialog" role="dialog" aria-modal="true" aria-labelledby="auth-title"><button v-if="!required" class="auth-close" :aria-label="text('关闭','Close')" @click="emit('close')">×</button><p class="auth-brand">MHP · 1.0.0</p><h2 id="auth-title">{{ mode==='reset'?text('找回密码','Reset password'):mode==='register'?text('注册账号','Create account'):text('登录账号','Sign in') }}</h2><div class="auth-tabs"><button :class="{active:mode==='login'}" @click="switchMode('login')">{{ text('登录','Sign in') }}</button><button :class="{active:mode==='register'}" @click="switchMode('register')">{{ text('注册','Register') }}</button></div><p>{{ mode==='reset'?text('填写注册邮箱，获取找回密码验证码。重置后所有设备需重新登录。','Use your registered email. All devices must sign in again after reset.'):mode==='register'?text('邮箱验证只在注册时使用。注册后本设备默认自动登录。旧账号可在这里一次性绑定密码，原有数据保留。','Verify your email once. This device stays signed in by default. Existing accounts can bind a password once without losing data.'):text('使用邮箱和密码登录。已记住的设备会自动进入，无需重复验证码。','Sign in with email and password. Remembered devices restore their session automatically.') }}</p><form @submit.prevent="submit"><label v-if="mode==='register'">{{ text('用户名','Username') }}<input v-model="username" name="username" maxlength="20" autocomplete="nickname" required /></label><label>{{ text('邮箱','Email') }}<input v-model="email" name="email" type="email" autocomplete="username" required @input="challenge=''"/></label><div v-if="mode!=='login'" class="auth-code-row"><label>{{ text('邮箱验证码','Email code') }}<input v-model="code" name="code" pattern="[0-9]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code" required /></label><button type="button" :disabled="busy||cooldown>0||!enabled||!email" @click="send">{{ cooldown?cooldown+'s':text('获取验证码','Send code') }}</button></div><label>{{ text('密码（10–128个字符）','Password (10–128 characters)') }}<input v-model="password" name="password" type="password" :autocomplete="mode!=='login'?'new-password':'current-password'" minlength="10" maxlength="128" required /></label><button v-if="mode==='login'" type="button" class="auth-link" :disabled="busy" @click="switchMode('reset')">{{ text('忘记密码？','Forgot password?') }}</button><button v-if="mode==='reset'" type="button" class="auth-link" :disabled="busy" @click="switchMode('login')">{{ text('返回登录','Back to sign in') }}</button><label v-if="mode!=='login'">{{ text('确认密码','Confirm password') }}<input v-model="confirmation" type="password" autocomplete="new-password" minlength="10" maxlength="128" required /></label><label v-if="mode!=='reset'" class="auth-remember"><input v-model="remember" type="checkbox" />{{ text('记住此设备，自动登录','Remember this device') }}</label><small>{{ text('主动退出、清理浏览器资料或会话失效后，使用密码重新登录。','Use your password again after signing out, clearing browser data, or session expiry.') }}</small><p v-if="mode!=='login'&&!enabled" class="auth-error">{{ text('邮箱注册通道暂不可用，请联系管理员。','Email registration is unavailable.') }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="error" class="auth-error" role="alert">{{ error }}</p><button class="btn-primary auth-submit" :disabled="busy||(mode!=='login'&&(!challenge||code.length!==6||!enabled))">{{ busy?text('处理中…','Working…'):mode==='reset'?text('重置密码','Reset password'):mode==='register'?text('注册并进入','Register & continue'):text('登录','Sign in') }}</button></form><p v-if="!isNative" class="auth-download"><a href="/download.html">{{ text('客户端发布状态','Desktop app status') }}</a></p></section></div></template>
<style scoped>.auth-overlay{position:fixed;inset:0;z-index:200;background:#080b16bb;backdrop-filter:blur(8px);display:grid;place-items:center;padding:20px;overflow:auto}.auth-dialog{position:relative;width:min(460px,100%);max-height:95vh;overflow:auto;padding:28px;background:var(--bg-card-strong);border:1px solid var(--border-glow);border-radius:20px;box-shadow:var(--shadow-card);color:var(--text-primary)}.auth-brand{color:var(--neon-blue);font-weight:800}.auth-dialog h2{margin:12px 0}.auth-dialog p,.auth-dialog small{font-size:13px;line-height:1.7}.auth-dialog form,.auth-dialog label{display:grid;gap:8px}.auth-dialog form{gap:15px}.auth-dialog input:not([type=checkbox]){width:100%;min-width:0;padding:11px;border:1px solid var(--border-dim);border-radius:9px;background:var(--bg-glass);color:var(--text-primary);font:inherit}.auth-dialog button{color:var(--text-primary);border:1px solid var(--border-dim);border-radius:9px;padding:9px 15px;background:var(--bg-sidebar);cursor:pointer}.auth-dialog button:disabled{opacity:.5;cursor:not-allowed}.auth-dialog .auth-link{justify-self:start;padding:0;background:transparent;border:0;color:var(--neon-blue);font-size:13px;text-decoration:underline;text-underline-offset:3px}.auth-dialog input:focus{outline:2px solid var(--neon-blue)}.auth-tabs{display:flex;gap:10px;margin-bottom:12px}.auth-tabs .active{border-color:var(--neon-blue)}.auth-code-row{display:grid;grid-template-columns:1fr auto;align-items:end;gap:10px}.auth-dialog .auth-remember{display:flex;align-items:center}.auth-error{color:#f58c8c}.auth-close{position:absolute;right:12px;top:12px}.auth-download a{color:var(--neon-blue)}.auth-submit{width:100%}</style>
